v.grid(); v.axes();
const a = P.a, r = H.clamp(P.r, -0.95, 0.95), N = Math.round(H.clamp(P.N, 1, 12));
const term = (n) => a * Math.pow(r, n - 1);
const partial = (k) => Math.abs(1 - r) < 1e-9 ? a * k : a * (1 - Math.pow(r, k)) / (1 - r);
const Sinf = Math.abs(r) < 1 ? a / (1 - r) : NaN;
if (Number.isFinite(Sinf)) {
  v.line(0, H.clamp(Sinf, 0, 9.8), 13, H.clamp(Sinf, 0, 9.8), { color: H.colors.good, width: 2, dash: [6, 6] });
}
const stair = [[0, 0]];
for (let k = 1; k <= N; k++) {
  const y = H.clamp(partial(k), 0, 9.8);
  stair.push([k, H.clamp(partial(k - 1), 0, 9.8)]);
  stair.push([k, y]);
}
v.path(stair, { color: H.colors.accent, width: 2.5 });
for (let k = 1; k <= N; k++) {
  v.dot(k, H.clamp(partial(k), 0, 9.8), { r: 4, fill: H.colors.accent });
